1	import { test, describe } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { parsePointer } from '../jsonpatch.mjs';
4	
5	describe('parsePointer valid', () => {
6	  const cases = [
7	    ['', []],
8	    ['/', ['']],
9	    ['/a//b/', ['a', '', 'b', '']],
10	    ['/~01', ['~1']],
11	    ['/~10', ['/0']],
12	    ['/~0~1', ['~', '/']],
13	    ['/~1~0', ['/', '~']],
14	    ['/a~1b', ['a/b']],
15	    ['/~0', ['~']],
16	    ['/é/日本', ['é', '日本']],
17	    ['/a b', ['a b']],
18	  ];
19	  for (const [pointer, tokens] of cases) {
20	    test(`parses ${JSON.stringify(pointer)}`, () => {
21	      assert.deepEqual(parsePointer(pointer), tokens);
22	    });
23	  }
24	
25	  test('returns a new array each call', () => {
26	    const first = parsePointer('/a/b');
27	    const second = parsePointer('/a/b');
28	    assert.notEqual(first, second);
29	    first.push('x');
30	    first[0] = 'changed';
31	    assert.deepEqual(parsePointer('/a/b'), ['a', 'b']);
32	    const e1 = parsePointer('');
33	    e1.push('x');
34	    assert.deepEqual(parsePointer(''), []);
35	  });
36	});
37	
38	describe('parsePointer invalid', () => {
39	  const bad = ['a', ' /a', '#/a', '/~', '/~2', '/a~', '/~a', '/~~0', '/a/~/b', '~0'];
40	  for (const pointer of bad) {
41	    test(`rejects ${JSON.stringify(pointer)}`, () => {
42	      assert.throws(
43	        () => parsePointer(pointer),
44	        (err) => {
45	          assert.ok(err instanceof SyntaxError);
46	          assert.equal(err.message, 'invalid pointer');
47	          return true;
48	        },
49	      );
50	    });
51	  }
52	});
53	
54	describe('parsePointer non-string', () => {
55	  const values = [
56	    ['String object', new String('/a')],
57	    ['empty String object', new String('')],
58	    ['undefined', undefined],
59	    ['null', null],
60	    ['number', 1],
61	    ['array', ['/a']],
62	    ['object', {}],
63	    ['boolean', true],
64	  ];
65	  for (const [label, value] of values) {
66	    test(`TypeError for ${label}`, () => {
67	      assert.throws(
68	        () => parsePointer(value),
69	        (err) => {
70	          assert.ok(err instanceof TypeError);
71	          assert.ok(!(err instanceof SyntaxError));
72	          assert.equal(err.message, 'pointer must be a string');
73	          return true;
74	        },
75	      );
76	    });
77	  }
78	
79	  test('no argument is a TypeError', () => {
80	    assert.throws(() => parsePointer(), { name: 'TypeError', message: 'pointer must be a string' });
81	  });
82	});
